import{_ as t,a as e}from"./chunks/gazebo-rbq-test.DTR2SerU.js";import{_ as a,o as i,c as o,a5 as d}from"./chunks/framework.Cct9zD0Q.js";const u=JSON.parse('{"title":"Gazebo","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/gazebo.md","filePath":"software/simulator/gazebo.md","lastUpdated":1795599730000}'),r={name:"software/simulator/gazebo.md"};function n(h,s,l,c,p,b){return i(),o("div",null,[...s[0]||(s[0]=[d('<h1 id="gazebo" tabindex="-1">Gazebo <a class="header-anchor" href="#gazebo" aria-label="Permalink to &quot;Gazebo&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Open-source Ignition Gazebo (Fortress) simulator for the RBQ quadruped robot.</strong></p><p>Gazebo runs the <strong>full RBQ software stack</strong>, so <strong>SLAM research, autonomous navigation tests and every test you would run on the real robot</strong> can be done in simulation. In addition, it bridges sensor data onto <strong>ROS 2</strong>, so external nodes (for example SLAM) can subscribe to the simulated IMU, LiDAR, TF, and joint states.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Gazebo</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+`" alt="Gazebo" width="600"></td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>src/</code></td><td>Simulator sources → <code>bin/rbq_gazebo</code></td></tr><tr><td><code>resources/</code></td><td>Worlds, robot/sensor URDFs, meshes</td></tr><tr><td><code>ros2/src/sensor_bridge/</code></td><td>colcon package: bridge launch, RViz config, DDS xml</td></tr><tr><td><code>scripts/</code></td><td>Build / run (<code>gazebo.bash</code>) / Docker scripts</td></tr></tbody></table><h2 id="run" tabindex="-1">Run with the RBQ stack <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run with the RBQ stack {#run}&quot;">​</a></h2><p class="sub-title">Install</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install dependencies (first time only)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/debian-dep.bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build rbq_gazebo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../</span></span></code></pre></div><hr class="sub-divider"><p class="sub-title">Local</p><p><code>scripts/sim.bash --no-sim</code> starts the RBQ core SW without its own simulator and opens the web UI (<code>http://127.0.0.1:8080</code>, <code>rb</code> / <code>rainbow2026</code>) once it is up; <code>--no-gui</code> skips the browser. Then start the simulator:</p><p><strong>Quadruped</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span></span></code></pre></div><p><strong>Wheeled RBQ</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wheel</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span></span></code></pre></div><p><strong>In one command</strong> — <code>--core</code> does both steps: the simulator script also starts the RBQ core SW (<code>scripts/sim.bash --no-sim</code>) with the robot variant, LiDAR and <code>-i</code> you give the simulator. <code>--vision</code> and <code>--no-gui</code> work as above. The core SW runs in its own terminal tabs and keeps running after the simulator stops; close those tabs to stop it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span></span></code></pre></div><hr class="sub-divider"><p class="sub-title">Docker</p><p>The simulator runs in Docker and joins the RBQ stack on the host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docker/run.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # quadruped</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docker/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # wheeled RBQ</span></span></code></pre></div><p><code>run.bash</code> handles <code>--headless</code>, <code>--build</code> and <code>--no-check</code>, and forwards every other argument to the simulator — so <code>--wheel</code>, <code>--livox</code> / <code>--ouster</code> and <code>--world &lt;name&gt;</code> pass straight through.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS networking</p><p>The simulator shares <strong>DDS domain 0</strong> on the loopback interface (<code>lo</code>) with the host RBQ stack. In Docker this is provided by <code>--network host</code>. Run only one simulator at a time: MuJoCo, Gazebo and Isaac Sim use the same topics.</p></div></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--wheel</code></td><td>Wheeled RBQ (12 leg joints + 4 driven wheels). Default is the quadruped</td></tr><tr><td><code>--livox</code></td><td>Livox Mid-360 x2 (front / rear). See <a href="#lidar">LiDAR</a></td></tr><tr><td><code>--ouster</code></td><td>Ouster OS1-32 x1 (rear deck). See <a href="#lidar">LiDAR</a></td></tr><tr><td><code>--world &lt;name&gt;</code></td><td>World to load. Default <code>empty</code>. See <a href="#worlds">Worlds</a></td></tr><tr><td><code>--headless</code></td><td>Run without the Gazebo window</td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS network interface. Default <code>lo</code></td></tr><tr><td><code>--rviz</code></td><td><code>gazebo.bash</code> only: also open RViz. See <a href="#ros2">ROS 2</a></td></tr><tr><td><code>--no-ros</code></td><td><code>gazebo.bash</code> only: Gazebo alone, without the ROS 2 bridge and RViz</td></tr><tr><td><code>--core</code></td><td><code>gazebo.bash</code> only: also start the RBQ core SW and open the web UI. With <code>--vision</code> it starts the Vision stack too; <code>--no-gui</code> skips the browser</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Variant</th><th>Robot</th><th>Model</th></tr></thead><tbody><tr><td><em>(none)</em></td><td>RBQ quadruped — 12 joints</td><td><code>resources/models/rbq10/</code></td></tr><tr><td><code>--wheel</code></td><td>Wheeled RBQ — 12 joints + 4 driven wheels</td><td><code>resources/models/rbq10_wheel/</code></td></tr></tbody></table><p><code>gazebo.bash</code> passes the matching <code>variant:=</code> to the sensor bridge, so RViz loads the same URDF.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — pass the variant to the RBQ stack too</p><p>Wheel state and references ride <code>SimInfo_.whl_joint</code> / <code>MotionRef_.whl_joint</code>, so the robot-side Motion must run with the same variant — start the stack with <code>bash scripts/sim.bash -r wheel</code> from the repository root.</p></div></div><hr class="sub-divider"><p class="sub-title" id="worlds">Worlds</p><table tabindex="0"><thead><tr><th>World</th><th><code>--world</code></th><th>Notes</th></tr></thead><tbody><tr><td>RBQ test world</td><td><code>empty</code> (default)</td><td>Stairs, obstacles, 20° / 30° slopes, slippery terrain, docking station</td></tr></tbody></table><p>Worlds are SDF files in <code>resources/worlds/</code>; <code>--world &lt;name&gt;</code> loads <code>resources/worlds/&lt;name&gt;.sdf</code>. On the first run Gazebo may download Fuel models.</p><table tabindex="0"><thead><tr><th style="text-align:center;">RBQ test world (default)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="`+e+`" alt="RBQ test world" width="600"></td></tr></tbody></table><h2 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors {#sensors}&quot;">​</a></h2><p class="sub-title" id="cameras">Cameras</p><p>The robot&#39;s six cameras are always in the model and publish on the same topics as MuJoCo, so the Vision stack (HAL) reads them unchanged:</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Camera</th><th>Streams</th></tr></thead><tbody><tr><td><code>sensor_0</code>–<code>sensor_3</code></td><td>Bottom (front, mid-front, mid-rear, rear)</td><td>depth, IR</td></tr><tr><td><code>sensor_4</code></td><td>Front</td><td>depth, RGB</td></tr><tr><td><code>sensor_5</code></td><td>Rear</td><td>depth, RGB</td></tr></tbody></table><p>Each camera is 640 x 360 at 15 fps. Topics are <code>rt/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code>, with <code>camera_info</code> and <code>tf</code> beside them.</p><hr class="sub-divider"><p class="sub-title" id="lidar">LiDAR</p><p>LiDAR is <strong>opt-in</strong> — nothing is spawned without a flag.</p><table tabindex="0"><thead><tr><th>Flag</th><th>LiDAR</th><th>Scan</th></tr></thead><tbody><tr><td><em>(none)</em></td><td>none</td><td>—</td></tr><tr><td><code>--livox</code></td><td>Livox Mid-360 x2, <code>lidar_front</code> (+35° up) / <code>lidar_rear</code> (−35° up)</td><td>gpu_lidar</td></tr><tr><td><code>--ouster</code></td><td>Ouster OS1-32 x1 on the rear deck, <code>lidar_ouster</code></td><td>32 ch × 1024</td></tr></tbody></table><p><code>gazebo.bash</code> forwards the same value to the sensor bridge as <code>lidar:=</code>, so one flag lines up all three:</p><ul><li><strong>Gazebo</strong> — the spawn URDF gets that LiDAR&#39;s <code>&lt;visual&gt;</code> (housing) + <code>&lt;sensor&gt;</code> (gpu_lidar) spliced in</li><li><strong>TF</strong> — static <code>base_link → lidar_front | lidar_rear | lidar_ouster</code></li><li><strong>RViz</strong> — loads the URDF generated for the same combination (<code>rbq10_livox.urdf</code>, …), housings included</li></ul><p>To feed it to SLAM, give the RBQ stack the same LiDAR: <code>bash scripts/sim.bash --slam --no-sim -p livox</code>, and do not use <code>--no-ros</code> — the cloud comes over the bridge. Gazebo has no per-LiDAR IMU or per-point time, so the frames SLAM reads are not deskewed.</p><hr class="sub-divider"><p class="sub-title" id="imu">IMU</p><p>The body IMU goes to Motion with the robot state every control cycle, and the bridge also publishes it as <code>/rbq/imu/IMU_state</code> (500 Hz). There is no per-LiDAR IMU; the Vision stack (HAL) uses the body IMU (<code>rt/rbq/imu</code>) for the LiDAR frames.</p><h2 id="ros2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros2" aria-label="Permalink to &quot;ROS 2 {#ros2}&quot;">​</a></h2><p>The <code>sensor_bridge</code> publishes on <strong>ROS 2 domain 0</strong> over loopback (<code>lo</code>). Run your node from <code>rbq_simulator/rbq_gazebo</code> with these environment variables (CycloneDDS is required to match the bridge):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RMW_IMPLEMENTATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rmw_cyclonedds_cpp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ROS_DOMAIN_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CYCLONEDDS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file://$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)/ros2/src/sensor_bridge/config/cyclonedds_gazebo.xml</span></span></code></pre></div><p>QoS is the <code>ros_gz_bridge</code> default, Reliable · KeepLast 10 for every topic (override per-topic in <code>ros2/src/sensor_bridge/config/bridge.yaml</code>):</p><div class="ros-topics"><table tabindex="0"><thead><tr><th>ROS 2 Topic</th><th>Type</th><th>Note</th></tr></thead><tbody><tr><td><code>/clock</code></td><td><code>rosgraph_msgs/msg/Clock</code></td><td>Sim time</td></tr><tr><td><code>/rbq/imu/IMU_state</code></td><td><code>sensor_msgs/msg/Imu</code></td><td>Body IMU</td></tr><tr><td><code>/rbq/lidar/lidar_front/points</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR cloud</td></tr><tr><td><code>/rbq/lidar/lidar_rear/points</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR cloud</td></tr><tr><td><code>/rbq/lidar/lidar_ouster/points</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR cloud</td></tr><tr><td><code>/tf</code></td><td><code>tf2_msgs/msg/TFMessage</code></td><td>Transforms</td></tr><tr><td><code>/joint_states</code></td><td><code>sensor_msgs/msg/JointState</code></td><td>Joint states</td></tr></tbody></table></div><p><code>/tf</code> carries two independent chains. <code>world → robot</code> is the Gazebo <strong>ground truth</strong> pose, published by the <code>rbq_gazebo</code> bridge. <code>local_world → base_link</code> is the <strong>state estimator</strong> output (IMU + leg odometry, origin at boot/reset), published by RBQ SW. Ground truth is deliberately attached to <code>robot</code> rather than <code>base_link</code> so the two never compete for the same parent frame.</p><p><code>/rbq/odometry</code>, <code>/rbq/imu</code> and <code>/rbq/joint_states</code> come from the RBQ stack over DDS, not the bridge. Under <code>--sim</code> they use the simulation clock, so <code>use_sim_time</code> nodes see one time base.</p><p><code>--rviz</code> opens RViz with the bundled sensor view (<code>ros2/src/sensor_bridge/rviz/rbq_sensors.rviz</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/gazebo.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --livox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span></span></code></pre></div><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING — RViz is empty without the RBQ stack</p><p>RViz&#39;s Fixed Frame <code>local_world</code> comes from the RBQ stack, not from Gazebo. Start <code>bash scripts/sim.bash --vision --no-sim</code> alongside it, or set the Fixed Frame to <code>world</code>.</p></div></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> — MuJoCo simulator</li><li><a href="/RBQ/nightly/software/simulator/isaac-sim.html">Isaac Sim</a> — Isaac Sim simulator</li><li><a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym</a> / <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> — RL training environments</li><li><a href="/RBQ/nightly/software/simulator/overview.html">Simulator overview</a></li></ul>`,62)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
